#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int N = 50005;
const int MAX_V = 1024;
const int NEG_INF = -1e9;

int n, m;
int A[N];
vector<int> adj[N];

int fa[N], dep[N], siz[N], son[N];
int top_node[N], dfn[N], rnk[N], tot;

void dfs1(int u, int p, int d) {
    fa[u] = p;
    dep[u] = d;
    siz[u] = 1;
    son[u] = 0;
    int max_siz = 0;
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs1(v, u, d + 1);
        siz[u] += siz[v];
        if (siz[v] > max_siz) {
            max_siz = siz[v];
            son[u] = v;
        }
    }
}

void dfs2(int u, int t) {
    top_node[u] = t;
    dfn[u] = ++tot;
    rnk[tot] = u;
    if (son[u]) dfs2(son[u], t);
    for (int v : adj[u]) {
        if (v == fa[u] || v == son[u]) continue;
        dfs2(v, v);
    }
}

struct Node {
    vector<int> dp[6]; 
    
    Node() {
        for (int s = 0; s < 6; ++s) {
            dp[s].assign(MAX_V, NEG_INF);
        }
    }
    
    void init(int val) {
        for (int s = 0; s < 6; ++s) {
            fill(dp[s].begin(), dp[s].end(), NEG_INF);
        }
        dp[0][0] = 0;
        dp[3][val] = val;
    }
    
    void reverse() {
        swap(dp[1], dp[2]);
    }
};

Node tree[N << 2];

Node merge(const Node& l, const Node& r) {
    Node res;
    for (int s = 0; s < 6; ++s) {
        fill(res.dp[s].begin(), res.dp[s].end(), NEG_INF);
    }
    
    for (int sl = 0; sl < 6; ++sl) {
        for (int xl = 0; xl < MAX_V; ++xl) {
            if (l.dp[sl][xl] == NEG_INF) continue;
            for (int sr = 0; sr < 6; ++sr) {
                for (int xr = 0; xr < MAX_V; ++xr) {
                    if (r.dp[sr][xr] == NEG_INF) continue;
                    
                    int left_has_right = (sl & 2);
                    int right_has_left = (sr & 1);
                    
                    int base = l.dp[sl][xl] + r.dp[sr][xr];
                    int new_val = 0;
                    int new_s = 0;
                    
                    if (left_has_right && right_has_left) {
                        base -= xl;
                        base -= xr;
                        new_val = xl ^ xr;
                        base += new_val;
                        new_s = (sl & 1) | ((sr & 2) << 0);
                    } else {
                        new_s = (sl & 1) | ((sr & 2) << 0);
                        if (left_has_right) {
                            new_val = xl;
                        } else if (right_has_left) {
                            new_val = xr;
                        } else {
                            new_val = 0;
                        }
                    }
                    
                    if (new_s <= 5 && base > res.dp[new_s][new_val]) {
                        res.dp[new_s][new_val] = base;
                    }
                }
            }
        }
    }
    return res;
}

void build(int rt, int l, int r) {
    if (l == r) {
        tree[rt].init(A[rnk[l]]);
        return;
    }
    int mid = (l + r) >> 1;
    build(rt << 1, l, mid);
    build(rt << 1 | 1, mid + 1, r);
    tree[rt] = merge(tree[rt << 1], tree[rt << 1 | 1]);
}

void update(int rt, int l, int r, int pos, int val) {
    if (l == r) {
        tree[rt].init(val);
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(rt << 1, l, mid, pos, val);
    else update(rt << 1 | 1, mid + 1, r, pos, val);
    tree[rt] = merge(tree[rt << 1], tree[rt << 1 | 1]);
}

Node query(int rt, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) {
        return tree[rt];
    }
    int mid = (l + r) >> 1;
    if (qr <= mid) return query(rt << 1, l, mid, ql, qr);
    if (ql > mid) return query(rt << 1 | 1, mid + 1, r, ql, qr);
    return merge(query(rt << 1, l, mid, ql, qr), query(rt << 1 | 1, mid + 1, r, ql, qr));
}

Node query_path(int u, int v, int k) {
    Node resL, resR;
    bool hasL = false, hasR = false;
    
    while (top_node[u] != top_node[v]) {
        if (dep[top_node[u]] > dep[top_node[v]]) {
            Node cur = query(1, 1, n, dfn[top_node[u]], dfn[u]);
            if (hasL) {
                resL = merge(cur, resL);
            } else {
                resL = cur;
                hasL = true;
            }
            u = fa[top_node[u]];
        } else {
            Node cur = query(1, 1, n, dfn[top_node[v]], dfn[v]);
            cur.reverse();
            if (hasR) {
                resR = merge(resR, cur);
            } else {
                resR = cur;
                hasR = true;
            }
            v = fa[top_node[v]];
        }
    }
    
    Node final_res;
    if (dep[u] < dep[v]) {
        final_res = query(1, 1, n, dfn[u], dfn[v]);
    } else {
        final_res = query(1, 1, n, dfn[v], dfn[u]);
        final_res.reverse();
    }
    
    if (hasL) final_res = merge(resL, final_res);
    if (hasR) final_res = merge(final_res, resR);
    
    return final_res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    if (!(cin >> n >> m)) return 0;
    
    for (int i = 1; i <= n; ++i) {
        cin >> A[i];
    }
    
    for (int i = 1; i < n; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    
    dfs1(1, 0, 1);
    dfs2(1, 1);
    build(1, 1, n);
    
    while (m--) {
        int op;
        cin >> op;
        if (op == 1) {
            int u, x;
            cin >> u >> x;
            update(1, 1, n, dfn[u], x);
        } else if (op == 2) {
            int u, v, k;
            cin >> u >> v >> k;
            Node ans_node = query_path(u, v, k);
            int ans = NEG_INF;
            for (int s = 0; s < 6; ++s) {
                for (int x = 0; x < MAX_V; ++x) {
                    if (ans_node.dp[s][x] > ans) {
                        ans = ans_node.dp[s][x];
                    }
                }
            }
            cout << ans << "\n";
        }
    }
    
    return 0;
}
